/* Standalone interaction prototype. Intentionally no network or persistent personal data. */
'use strict';
const $ = (s) => document.querySelector(s);
const esc = (s = '') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let nextId = 30;
const uid = () => String(++nextId);
const localDate = (offset = 0) => { const d = new Date(); d.setDate(d.getDate() + offset); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const dayLabel = (date) => new Date(`${date}T12:00:00`).toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
const state = {
  tasks:[
    {id:'1',title:'Написать семье и предложить две даты поездки',projectId:'p1',horizon:'now',status:'active',notes:'Предложить 12–15 и 19–22 декабря. Спросить, какие даты удобнее.'},
    {id:'2',title:'Открыть прототип и записать три замечания к разбору входящих',projectId:'p2',horizon:'now',status:'active',notes:'Проверить, легко ли из одной записи создать несколько результатов.'},
    {id:'3',title:'Написать в магазин и уточнить дату доставки',horizon:'now',status:'active',notes:'Номер заказа лежит в письме от магазина.'},
    {id:'4',title:'Выписать три варианта жилья рядом с парком',projectId:'p1',horizon:'week',status:'active',notes:''},
    {id:'5',title:'Позвонить в мастерскую и узнать часы приёма',horizon:'later',status:'active',notes:''}
  ],
  inbox:[
    {id:'i1',text:'Обсудили поездку. Нужно согласовать даты, выбрать жильё. Договорились созвониться в пятницу вечером. Сохранить варианты рядом с парком.',source:'После разговора'},
    {id:'i2',text:'Найти гарантию на кофемашину. Кажется, письмо с чеком осталось в почте.',source:'Мысль'},
    {id:'i3',text:'Когда-нибудь устроить выходные без телефона и выбраться за город.',source:'Мысль'}
  ],
  projects:[
    {id:'p1',title:'Семейная поездка',outcome:'Согласованы даты и забронировано жильё, которое устраивает всех.',purpose:'Побыть вместе и сменить обстановку.',minimum:'Две ночи в удобном месте без сложной программы.',plan:'Согласовать даты → выбрать жильё → забронировать → собрать вещи.\nЭто ориентир. В рабочем списке находятся только ближайшие действия.'},
    {id:'p2',title:'Моё приложение для задач',outcome:'Могу записать мысль, разобрать её и выбрать следующий шаг на телефоне и компьютере.',purpose:'Меньше держать в голове и проще возвращаться к делам.',minimum:'Один надёжный путь от входящего до выполненного действия.',plan:'Сначала проверить сценарии на макете. Затем реализовать хранение и синхронизацию.'},
    {id:'p3',title:'Удобное рабочее место',outcome:'На столе достаточно места и удобно работать вечером.',purpose:'Меньше уставать от рабочего пространства.',minimum:'Освободить поверхность и выбрать положение лампы.',plan:'Пока не определён.'}
  ],
  ideas:[{id:'a1',title:'Выходные в маленьком городе',reason:'Хочется неспешной прогулки и смены обстановки. Без плотной программы.',reviewed:false},{id:'a2',title:'Собрать семейные истории',reason:'Сохранить рассказы родителей, пока можно спросить подробности.',reviewed:false}],
  waiting:[{id:'w1',person:'Анна',result:'Два варианта дат для встречи',checkOn:localDate(),done:false}],
  events:[{id:'e1',title:'Созвон по поездке',date:localDate(),time:'15:00',end:'15:30',notes:'Согласовать удобные даты'}],
  materials:[{id:'m1',title:'Как выбирать следующий шаг',body:'Если путь непонятен, выпишите вопрос, на который нужно получить ответ. Затем выберите небольшое действие для получения этой информации.'}],
  reviews:{daily:{index:0,states:[]},weekly:{index:0,states:[]}},drafts:{},focus:null
};
let selectedInbox='i1', actionTab='now', reviewKind='weekly', currentProject='p1', previousFocus=null, toastTimer;
const names={now:'Сейчас',tasks:'Действия',inbox:'Входящие',projects:'Проекты',review:'Обзор',ideas:'Идеи',waiting:'Ожидания',calendar:'Календарь',materials:'Материалы',settings:'Настройки',more:'Ещё',focus:'Фокус',project:'Проект'};
const primary=['now','tasks','inbox','projects','review'];
const secondary=['ideas','waiting','calendar','materials','settings'];
const route=()=>location.hash.slice(1)||'now';
const projectName=id=>state.projects.find(p=>p.id===id)?.title || '';
const button=(action,label,cls='',data='')=>`<button class="${cls}" data-action="${action}" ${data}>${label}</button>`;
const pageHead=(title,subtitle,action='')=>`<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function go(page){if(route()===page)render();else location.hash=page;}
function navigation(){
  const navButton=k=>`<button class="nav-item ${route()===k?'active':''}" data-go="${k}" ${route()===k?'aria-current="page"':''}>${names[k]}${k==='inbox'?`<span class="count">${state.inbox.length}</span>`:''}</button>`;
  $('#navigation').innerHTML=primary.map(navButton).join('')+'<div class="nav-divider"></div>'+secondary.map(navButton).join('');
  $('#mobile-navigation').innerHTML=['now','inbox','review','more'].map(k=>`<button data-go="${k}" class="${route()===k?'active':''}" ${route()===k?'aria-current="page"':''}>${names[k]}</button>`).join('');
  $('#breadcrumb').textContent=names[route()]||'Ясный шаг';
}
function taskRows(tasks,featured=false){return tasks.length?`<div class="list">${tasks.map((t,i)=>`<div class="task-row ${featured&&i===0?'featured':''}"><button class="check" data-action="complete" data-id="${t.id}" aria-label="Выполнить: ${esc(t.title)}"><span></span></button><div class="task-info"><button class="task-title" data-action="edit-task" data-id="${t.id}">${esc(t.title)}</button><div class="task-meta">${esc(projectName(t.projectId)||'Личное')}${t.due?` · Реальный срок: ${dayLabel(t.due)}`:''}</div></div><div class="row-actions">${button('focus','Начать',featured&&i===0?'primary':'quiet',`data-id="${t.id}"`)}</div></div>`).join('')}</div>`:`<div class="empty"><h2>Можно оставить место свободным</h2><p>Выберите действие из недели, пересмотрите планы или отдохните.</p>${button('choose-week','Посмотреть неделю')}</div>`;}
function nowScreen(){const tasks=state.tasks.filter(t=>t.status==='active'&&t.horizon==='now');return `<div class="date">${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</div>${pageHead('Сейчас','Вы уже подумали. Можно сделать следующий шаг.')}<div class="columns"><section><h2 class="section-label">Выбрано на сейчас · ${tasks.length}</h2>${taskRows(tasks,true)}<div class="toolbar">${button('choose-week','Выбрать из недели','quiet')}${button('new-task','Добавить действие','quiet')}</div><div class="hint">Необязательно закончить весь список.<br>Если обстоятельства изменились, пересмотрите выбор.</div></section><aside class="context-column"><section class="side-section"><h2>Договорённости сегодня</h2>${state.events.filter(e=>e.date===localDate()).map(e=>`<div class="appointment"><time>${esc(e.time)}</time><div><strong>${esc(e.title)}</strong><small>до ${esc(e.end)}</small></div></div>`).join('')||'<p class="subtle">Встреч пока нет.</p>'}<button class="quiet" data-go="calendar">Открыть календарь</button></section><section class="side-section"><h2>Время подумать</h2><p class="subtle">Обзор помогает обновить договорённости с собой и отпустить лишнее.</p><button data-go="review">Открыть обзор</button></section><section><h2 class="section-label">Всё записанное — не обещание</h2><p class="subtle">Идеи могут оставаться идеями. Материалы не требуют галочки «сделано».</p></section></aside></div>`;}
function tasksScreen(){return `${pageHead('Действия','Понятные шаги в одном списке.',button('new-task','＋ Действие','primary'))}<div class="tabs">${[['now','Сейчас'],['week','Неделя'],['later','Позже'],['done','Завершённые']].map(([k,l])=>button('task-tab',l,k===actionTab?'selected':'',`data-id="${k}"`)).join('')}</div>${actionTab==='done'?`<div class="list">${state.tasks.filter(t=>t.status==='done').map(t=>`<div class="task-row"><div class="task-info"><strong>${esc(t.title)}</strong><div class="task-meta">Выполнено · ${esc(projectName(t.projectId)||'Личное')}</div></div>${button('restore-task','Вернуть','quiet',`data-id="${t.id}"`)}</div>`).join('')||'<div class="paper">Завершённых действий пока нет.</div>'}</div>`:taskRows(state.tasks.filter(t=>t.status==='active'&&t.horizon===actionTab))}<p class="subtle spaced">«Сейчас», «Неделя» и «Позже» — выбор горизонта. Реальный срок указывается отдельно и может отсутствовать.</p>`;}
const kinds={task:'Действие',project:'Проект',event:'Встреча',material:'Материал',idea:'Идея'};
function inboxScreen(){
 const item=state.inbox.find(i=>i.id===selectedInbox)||state.inbox[0];if(!item)return `${pageHead('Входящие','Здесь хранится то, что ещё нужно обдумать.')}<div class="empty"><h2>Всё разобрано</h2><p>Результаты сохранены в соответствующих разделах. Можно вернуться к действиям.</p><button data-go="now">Перейти к действиям</button></div>`;
 selectedInbox=item.id; const draft=state.drafts[item.id] ||= {outputs:[],type:'task',text:''};
 return `${pageHead('Разобрать входящие','Одна запись может дать несколько разных результатов.')}<div class="inbox-layout"><div class="list inbox-queue">${state.inbox.map(i=>`<button class="inbox-item ${i.id===item.id?'active':''}" data-action="select-inbox" data-id="${i.id}">${esc(i.text.length>80?i.text.slice(0,80)+'…':i.text)}<small>${esc(i.source||'Мысль')}</small></button>`).join('')}</div><section class="paper"><h2 class="section-label">Исходная запись</h2><div class="source">${esc(item.text)}</div><h2>Что из этого следует?</h2><form id="process-form"><label class="field">Тип результата<select name="kind" id="result-kind">${Object.entries(kinds).map(([k,l])=>`<option value="${k}" ${k===draft.type?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span id="result-label">${draft.type==='task'?'Что конкретно сделать?':'Название или содержание'}</span><textarea name="text" id="result-text" required maxlength="2000" placeholder="Например: написать семье и предложить две даты">${esc(draft.text)}</textarea></label><div id="event-fields" ${draft.type==='event'?'':'hidden'}>${eventFields()}</div><button type="submit">Добавить в результаты</button></form><div class="results"><h3>Результаты разбора · ${draft.outputs.length}</h3>${draft.outputs.map((o,i)=>`<div class="result-row"><span><small>${kinds[o.type]}</small><br>${esc(o.text)}</span>${button('remove-output','Убрать','quiet',`data-id="${i}"`)}</div>`).join('')||'<p class="subtle">Добавьте всё нужное, затем завершите разбор.</p>'}<div class="toolbar"><button class="primary" data-action="finish-processing" ${draft.outputs.length?'':'disabled'}>Завершить разбор</button>${button('discard-inbox','Не нужно','quiet')}</div><p class="subtle">В этой демонстрации результаты сохраняются до обновления страницы. Связывание новых задач с проектом доступно затем в карточке действия.</p></div></section></div>`;
}
function projectsScreen(){return `${pageHead('Проекты','Результат впереди. Ближайший шаг — под рукой.',button('new-project','＋ Проект','primary'))}<div class="list">${state.projects.map(p=>{const n=state.tasks.filter(t=>t.projectId===p.id&&t.status==='active').length;return `<article class="project-row"><div><h2>${esc(p.title)}</h2><p>${esc(p.outcome)}</p><span class="tag ${n?'':'attention'}">${n?`Ближайших действий: ${n}`:'Нужен следующий шаг'}</span></div>${button('open-project','Открыть','quiet',`data-id="${p.id}"`)}</article>`;}).join('')}</div><div class="hint">План помогает думать о проекте. В список действий попадают только шаги, которые уже можно начать.</div>`;}
function projectScreen(){const p=state.projects.find(p=>p.id===currentProject);if(!p)return projectsScreen();return `<div class="project-detail"><button class="quiet back" data-go="projects">‹ Все проекты</button>${pageHead(esc(p.title),'К какому результату вы хотите прийти?')}<p class="outcome">${esc(p.outcome)}</p><h2>Ближайшие действия</h2>${taskRows(state.tasks.filter(t=>t.projectId===p.id&&t.status==='active'))}<div class="toolbar">${button('project-task','＋ Определить следующий шаг','primary',`data-id="${p.id}"`)}</div><div class="detail-section"><h2>Что это даст?</h2><p>${esc(p.purpose||'Можно уточнить по мере работы.')}</p></div><div class="detail-section"><h2>Минимально полезный результат</h2><p>${esc(p.minimum||'Какой небольшой результат уже будет иметь ценность?')}</p></div><details class="paper spaced"><summary>План и заметки — справочная информация</summary><p class="material-body spaced">${esc(p.plan||'План пока не определён. Это не мешает выбрать следующий шаг.')}</p></details></div>`;}
const reviewSteps={
 daily:[['Завершённое','Не появился ли следующий шаг после сделанного?','Посмотрите завершённые действия. Если за ними есть продолжение, сформулируйте его.','tasks'],['Предыдущий выбор','Что стоит переформулировать или отпустить?','Оставлять каждую задачу в планах необязательно. Перепишите, перенесите или отмените её.','tasks'],['Договорённости','Что нужно учесть в ближайший день?','Проверьте встречи и реальные сроки. Не заполняйте всё свободное время задачами.','calendar'],['Посильный выбор','С чем вы хотите начать следующий отрезок?','Выберите понятные действия и оставьте место для отдыха и неожиданностей.','now']],
 weekly:[['Источники входящих','Где ещё осталось необдуманное?','Загляните во входящие, заметки и свои источники. Большой старый архив можно разбирать отдельными короткими подходами.','inbox'],['Актуальность действий','Всё ли это по-прежнему нужно делать?','Можно отменить ненужное, уточнить формулировку или вернуть задачу в «Позже».','tasks'],['Проекты','Есть ли понятный шаг у каждого активного проекта?','Если непонятно, что делать, выберите маленькое действие для получения новой информации.','projects'],['Результаты и ожидания','После сделанного нужно что-то продолжить или проверить?','Вспомните результаты недели и договорённости с людьми.','waiting'],['Календарь','Что понадобится в ближайшие две недели?','Посмотрите договорённости заранее. Подготовку к встрече запишите отдельным действием.','calendar'],['Неделя и восстановление','Какой выбор будет для вас посильным?','Сверьте планы с обстоятельствами. Необязательно брать на себя всё; оставьте место для личного и отдыха.','tasks']]
};
function reviewScreen(){const steps=reviewSteps[reviewKind],r=state.reviews[reviewKind];if(r.finished)return `${pageHead('Обзор сохранён',r.states.includes('skipped')?'Часть пунктов пропущена. Это частичный обзор.':'Вы прошли все пункты обзора.')}<div class="paper"><h2>Система стала немного яснее</h2><p>Можно вернуться к работе или сделать паузу. Не нужно завершать все дела, чтобы закончить обзор.</p><div class="toolbar"><button class="primary" data-go="now">К действиям</button>${button('restart-review','Посмотреть обзор ещё раз','quiet')}</div></div>`;
 const step=steps[r.index];return `${pageHead('Обзор системы','Время обновить планы и освободить голову.')}<div class="tabs">${button('review-kind','Ежедневный',reviewKind==='daily'?'selected':'','data-id="daily"')}${button('review-kind','Еженедельный',reviewKind==='weekly'?'selected':'','data-id="weekly"')}</div><div class="review-layout"><ol class="review-steps">${steps.map((s,i)=>`<li class="${i===r.index?'current':r.states[i]||''}">${r.states[i]==='done'?'✓ ':r.states[i]==='skipped'?'— ':`${i+1}. `}${s[0]}</li>`).join('')}</ol><section class="paper"><p class="subtle">Шаг ${r.index+1} из ${steps.length}</p><div class="progress"><span style="width:${r.index/steps.length*100}%"></span></div><h2 class="review-question">${step[1]}</h2><p class="muted">${step[2]}</p><button data-go="${step[3]}">Открыть: ${names[step[3]]}</button><div class="hint">Вернитесь в «Обзор» после просмотра. В прототипе прогресс сохраняется только до обновления вкладки.</div><div class="toolbar">${button('review-done',r.index===steps.length-1?'Завершить обзор':'Проверено, дальше','primary')}${button('review-skip','Пропустить','quiet')}</div>${button('review-exit','Сохранить и выйти','quiet')}</section></div>`;}
function ideasScreen(){return `${pageHead('Идеи','Интерес — ещё не обязательство.',button('new-idea','＋ Идея','primary'))}<div class="list">${state.ideas.map(i=>`<article class="idea"><h2>${esc(i.title)}</h2><p>${esc(i.reason)}</p><small>${i.reviewed?'Пересмотрено в этой сессии':'Пора спокойно перечитать'}</small><div class="toolbar">${button('idea-reviewed','Оставить после просмотра','quiet',`data-id="${i.id}"`)}${button('idea-project','Создать проект','',`data-id="${i.id}"`)}${button('archive-idea','В архив','quiet',`data-id="${i.id}"`)}</div></article>`).join('')||'<div class="paper">В инкубаторе пока пусто. Идея может появиться в любой момент.</div>'}</div><div class="hint">Что изменилось? Чем эта идея может пригодиться? Хочется ли с ней что-нибудь сделать — или её можно отпустить?</div>`;}
function waitingScreen(){return `${pageHead('Ожидания','Проверять договорённости, не удерживая их в голове.')}<div class="list">${state.waiting.filter(w=>!w.done).map(w=>`<article class="idea"><span class="tag">Проверить ${dayLabel(w.checkOn)}</span><h2 class="spaced">${esc(w.person)}: ${esc(w.result)}</h2><div class="toolbar">${button('control-waiting',w.controlId?'Открыть действие контроля':'Создать действие контроля','',`data-id="${w.id}"`)}${button('resolve-waiting','Результат получен','quiet',`data-id="${w.id}"`)}</div></article>`).join('')||'<div class="paper">Открытых ожиданий нет.</div>'}</div><p class="subtle spaced">Дата проверки — ваш ориентир. Приложение не отправляет сообщения другим людям.</p>`;}
function calendarScreen(){return `${pageHead('Календарь','Время, которое вы уже решили чему-то посвятить.',button('new-event','＋ Встреча','primary'))}<div class="list">${[...state.events].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(e=>`<article class="event-row"><time>${dayLabel(e.date)}<br>${esc(e.time)}–${esc(e.end)}</time><div><h2>${esc(e.title)}</h2><p>${esc(e.notes||'Время выделено для этой встречи.')}</p></div></article>`).join('')||'<div class="paper">Встреч пока нет.</div>'}</div><div class="hint">Гибкие действия живут в своём списке. В демонстрации встречи задаются в местном времени устройства, без синхронизации с внешними календарями.</div>`;}
function materialsScreen(){return `${pageHead('Материалы','То, что пригодится в нужный момент.')}<div class="list">${state.materials.map(m=>`<article class="idea"><h2>${esc(m.title)}</h2><p class="material-body">${esc(m.body)}</p></article>`).join('')}</div><p class="subtle spaced">Материал можно создать при разборе входящего. У справочной записи нет галочки выполнения.</p>`;}
function settingsScreen(){return `${pageHead('О прототипе','Демонстрация взаимодействий, а не хранилище ваших дел.')}<section class="paper"><h2>Что здесь работает</h2><p>Запись мысли, разбор в несколько результатов, редактирование действий, выбор горизонта, выполнение, создание проектов и встреч, фокус с таймером, прохождение обзора, инкубация идей.</p><h2>Что появится в приложении</h2><p>Надёжное хранение, синхронизация телефона и компьютера, аккаунт, офлайн-режим, резервные копии, разрешение конфликтов, полноценные редакторы и история изменений.</p><div class="notice">Сейчас данные живут только в памяти этой вкладки. Перезагрузка вернёт исходные примеры. Не вводите здесь важную информацию.</div>${button('reset','Сбросить демонстрацию')}<p class="subtle spaced">Описание, методика и ТЗ находятся в папке рядом с прототипом.</p></section>`;}
function moreScreen(){return `${pageHead('Ещё','Остальные части вашего пространства.')}<div class="more-grid">${['tasks','projects',...secondary].map(k=>`<button data-go="${k}">${names[k]}<small>${{tasks:'Все ближайшие действия',projects:'Результаты и следующие шаги',ideas:'Замыслы без обязательств',waiting:'Договорённости с людьми',calendar:'Выделенное время',materials:'Информация под рукой',settings:'Возможности и ограничения прототипа'}[k]}</small></button>`).join('')}</div>`;}
function focusScreen(){const f=state.focus,t=state.tasks.find(t=>t.id===f?.taskId);if(!t)return `${pageHead('Фокус','Выберите действие, с которым хотите поработать.')}<button data-go="now">К действиям</button>`;return `<div class="focus"><button class="quiet back" data-go="now">‹ Вернуться к списку</button><div class="paper"><p class="section-label">Сейчас достаточно одного шага</p><h1>${esc(t.title)}</h1><p class="muted">${esc(t.notes||projectName(t.projectId))}</p><div class="timer" id="timer" aria-label="Оставшееся время">${timerText()}</div><p class="subtle" id="timer-caption">${f.running?'Можно работать спокойно.':f.remaining===0?'Отрезок закончился. Можно сделать паузу.':'Таймер необязателен. Начните, когда удобно.'}</p><div class="tabs">${[15,25,40].map(n=>button('timer-duration',`${n} минут`,f.duration===n?'selected':'',`data-id="${n}"`)).join('')}</div><div class="toolbar">${button('timer-toggle',f.running?'Пауза':'Начать отрезок')}${button('focus-complete','Действие выполнено','primary')}</div>${button('capture','Записать отвлечение','quiet')}<p class="subtle spaced">Окончание таймера не завершает задачу автоматически.</p></div></div>`;}
function remaining(){const f=state.focus;return !f?0:f.running?Math.max(0,Math.ceil((f.endsAt-Date.now())/1000)):f.remaining;}
function timerText(){const sec=remaining();return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function render(){navigation();const screens={now:nowScreen,tasks:tasksScreen,inbox:inboxScreen,projects:projectsScreen,project:projectScreen,review:reviewScreen,ideas:ideasScreen,waiting:waitingScreen,calendar:calendarScreen,materials:materialsScreen,settings:settingsScreen,more:moreScreen,focus:focusScreen};$('#main').innerHTML=(screens[route()]||nowScreen)();}
function dialog(title,body){previousFocus=document.activeElement;$('#modal-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('close-modal','✕','quiet','aria-label="Закрыть"')}</div>${body}`;$('#modal').setAttribute('aria-labelledby','dialog-title');$('#modal').showModal();const field=$('#modal input, #modal textarea');if(field)field.focus();}
function closeDialog(){const m=$('#modal');if(m.querySelector('form')?.dataset.dirty==='true'&&!confirm('Закрыть без сохранения введённых изменений?'))return;m.close();previousFocus?.focus();}
function savedDialog(){const f=$('#modal form');if(f)f.dataset.dirty='false';$('#modal').close();render();}
function captureDialog(){dialog('Записать мысль',`<form id="capture-form"><p class="muted">Сейчас достаточно записать. Решить, что с этим делать, можно позже.</p><label class="field">Что занимает внимание?<textarea name="text" maxlength="20000" required placeholder="Мысль, обещание, вопрос…"></textarea></label><div class="dialog-actions">${button('close-modal','Отмена','quiet')}<button class="primary" type="submit">Сохранить во входящие</button></div></form>`);}
function projectOptions(selected){return `<option value="">Без проекта</option>${state.projects.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}`;}
function taskDialog(id,projectId){const t=state.tasks.find(t=>t.id===id);dialog(t?'Уточнить действие':'Следующее действие',`<form id="task-form" data-id="${t?.id||''}"><label class="field">Что конкретно сделать?<textarea name="title" maxlength="240" required>${esc(t?.title||'')}</textarea><small>Опишите действие, которое можно начать без дополнительных расшифровок.</small></label><label class="field">Подсказка для будущего себя<textarea name="notes">${esc(t?.notes||'')}</textarea></label><label class="field">Проект<select name="project">${projectOptions(t?.projectId||projectId)}</select></label><div class="field-row"><label class="field">Когда выбрать<select name="horizon">${[['now','Сейчас'],['week','На неделе'],['later','Позже']].map(([k,l])=>`<option value="${k}" ${(t?.horizon||'later')===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Реальный срок, если есть<input type="date" name="due" value="${t?.due||''}"><small>Можно оставить пустым.</small></label></div><div class="dialog-actions">${t?button('cancel-task','Отменить задачу','danger',`data-id="${t.id}"`):''}<button class="primary" type="submit">Сохранить действие</button></div></form>`);}
function projectDialog(ideaId){const idea=state.ideas.find(i=>i.id===ideaId);dialog('Новый проект',`<form id="project-form" data-idea="${ideaId||''}"><label class="field">Название<input name="title" required maxlength="240" value="${esc(idea?.title||'')}"></label><label class="field">Какой результат хотите получить?<textarea name="outcome" required></textarea></label><label class="field">Что это даст?<textarea name="purpose">${esc(idea?.reason||'')}</textarea></label><label class="field">Минимально полезный результат<input name="minimum"></label><div class="dialog-actions"><button class="primary" type="submit">Создать проект</button></div></form>`);}
function eventFields(){return `<label class="field">Дата<input name="date" type="date" value="${localDate()}" required></label><div class="field-row"><label class="field">Начало<input name="time" type="time" value="15:00" required></label><label class="field">Конец<input name="end" type="time" value="15:30" required></label></div>`;}
function newEventDialog(){dialog('Новая встреча',`<form id="event-form"><label class="field">Что запланировано?<input name="title" required maxlength="240"></label>${eventFields()}<div class="dialog-actions"><button class="primary" type="submit">Сохранить встречу</button></div></form>`);}
function finishProcessing(){const item=state.inbox.find(i=>i.id===selectedInbox),d=state.drafts[selectedInbox];if(!item||!d?.outputs.length)return;for(const o of d.outputs){const id=uid();if(o.type==='task')state.tasks.push({id,title:o.text,notes:'Из входящего: '+item.text,horizon:'later',status:'active'});if(o.type==='project')state.projects.push({id,title:o.text,outcome:o.text,purpose:'',plan:'Исходная запись: '+item.text});if(o.type==='idea')state.ideas.push({id,title:o.text,reason:'Из входящего: '+item.text});if(o.type==='material')state.materials.push({id,title:o.text,body:item.text});if(o.type==='event')state.events.push({id,title:o.text,date:o.date,time:o.time,end:o.end});}const count=d.outputs.length;state.inbox=state.inbox.filter(i=>i.id!==item.id);delete state.drafts[item.id];render();toast(`Разбор завершён. Создано результатов: ${count}. Действия находятся в «Позже».`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go){go(b.dataset.go);return;}const a=b.dataset.action,id=b.dataset.id;if(!a)return;if(b.closest('form'))e.preventDefault();const task=state.tasks.find(t=>t.id===id);
 if(a==='capture')captureDialog();
 else if(a==='close-modal')closeDialog();
 else if(a==='complete'){task.status='done';render();toast('Действие выполнено. Вернуть его можно в разделе «Завершённые».');}
 else if(a==='restore-task'){task.status='active';render();toast('Действие возвращено в прежний горизонт.');}
 else if(a==='edit-task')taskDialog(id);
 else if(a==='new-task')taskDialog();
 else if(a==='project-task')taskDialog(null,id);
 else if(a==='cancel-task'){task.status='cancelled';savedDialog();toast('Задача отменена. Она не считается выполненной.');}
 else if(a==='choose-week'){actionTab='week';go('tasks');}
 else if(a==='task-tab'){actionTab=id;render();}
 else if(a==='select-inbox'){selectedInbox=id;render();}
 else if(a==='remove-output'){state.drafts[selectedInbox].outputs.splice(Number(id),1);render();}
 else if(a==='finish-processing')finishProcessing();
 else if(a==='discard-inbox'){if(confirm('Убрать эту входящую запись и её черновик? В демонстрации корзины нет.')){state.inbox=state.inbox.filter(i=>i.id!==selectedInbox);delete state.drafts[selectedInbox];render();toast('Запись убрана из демонстрации.');}}
 else if(a==='new-project')projectDialog();
 else if(a==='open-project'){currentProject=id;go('project');}
 else if(a==='focus'){if(!state.focus||state.focus.taskId!==id)state.focus={taskId:id,duration:25,remaining:1500,running:false};go('focus');}
 else if(a==='timer-duration'){state.focus.duration=Number(id);state.focus.remaining=Number(id)*60;state.focus.running=false;render();}
 else if(a==='timer-toggle'){const f=state.focus;if(f.running){f.remaining=remaining();f.running=false;}else{if(f.remaining===0)f.remaining=f.duration*60;f.endsAt=Date.now()+f.remaining*1000;f.running=true;}render();}
 else if(a==='focus-complete'){state.tasks.find(t=>t.id===state.focus.taskId).status='done';state.focus=null;go('now');toast('Действие выполнено. Можно сделать паузу.');}
 else if(a==='review-kind'){reviewKind=id;render();}
 else if(a==='review-done'||a==='review-skip'){const r=state.reviews[reviewKind];r.states[r.index]=a==='review-done'?'done':'skipped';if(r.index===reviewSteps[reviewKind].length-1)r.finished=true;else r.index++;render();}
 else if(a==='review-exit'){go('now');toast('Прогресс обзора сохранён в памяти этой вкладки.');}
 else if(a==='restart-review'){state.reviews[reviewKind]={index:0,states:[]};render();}
 else if(a==='new-idea')dialog('Записать идею',`<form id="idea-form"><label class="field">Идея<input name="title" required maxlength="240"></label><label class="field">Почему хочется её сохранить?<textarea name="reason"></textarea></label><div class="dialog-actions"><button class="primary" type="submit">Сохранить идею</button></div></form>`);
 else if(a==='idea-reviewed'){const idea=state.ideas.find(i=>i.id===id);idea.reviewed=true;state.ideas=state.ideas.filter(i=>i.id!==id).concat(idea);render();toast('Идея пересмотрена и оставлена в инкубаторе.');}
 else if(a==='idea-project')projectDialog(id);
 else if(a==='archive-idea'){state.ideas=state.ideas.filter(i=>i.id!==id);render();toast('Идея убрана из очереди. История архива предусмотрена в полном приложении.');}
 else if(a==='control-waiting'){const w=state.waiting.find(w=>w.id===id);if(w.controlId){taskDialog(w.controlId);return;}const tid=uid();state.tasks.push({id:tid,title:`Написать ${w.person} и уточнить: ${w.result}`,horizon:'now',status:'active',notes:''});w.controlId=tid;render();toast('Действие контроля добавлено в «Сейчас».');}
 else if(a==='resolve-waiting'){state.waiting.find(w=>w.id===id).done=true;render();toast('Получение результата отмечено.');}
 else if(a==='new-event')newEventDialog();
 else if(a==='reset'&&confirm('Сбросить все изменения демонстрации?'))location.reload();
});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,d=new FormData(form),val=k=>String(d.get(k)||'').trim();
 if(form.id==='capture-form'){if(!val('text'))return;state.inbox.push({id:uid(),text:val('text'),source:'Только что записано'});savedDialog();toast('Мысль записана во входящие этой демонстрации.');}
 else if(form.id==='task-form'){if(!val('title'))return;const t=state.tasks.find(t=>t.id===form.dataset.id);const fields={title:val('title'),notes:val('notes'),projectId:val('project')||null,horizon:val('horizon'),due:val('due')};if(t)Object.assign(t,fields);else state.tasks.push({id:uid(),...fields,status:'active'});savedDialog();toast('Действие сохранено.');}
 else if(form.id==='process-form'){const draft=state.drafts[selectedInbox],type=val('kind');if(!val('text'))return;if(type==='event'&&val('end')<=val('time')){toast('Конец встречи должен быть позже начала.');return;}draft.outputs.push({type,text:val('text'),date:val('date'),time:val('time'),end:val('end')});draft.text='';render();toast('Результат добавлен. Можно добавить ещё один.');}
 else if(form.id==='project-form'){if(!val('title')||!val('outcome'))return;const id=uid();state.projects.push({id,title:val('title'),outcome:val('outcome'),purpose:val('purpose'),minimum:val('minimum'),plan:''});if(form.dataset.idea)state.ideas=state.ideas.filter(i=>i.id!==form.dataset.idea);currentProject=id;savedDialog();go('project');toast('Проект создан. Теперь можно выбрать ближайший шаг.');}
 else if(form.id==='idea-form'){if(!val('title'))return;state.ideas.push({id:uid(),title:val('title'),reason:val('reason')});savedDialog();toast('Идея сохранена без обязательства её выполнить.');}
 else if(form.id==='event-form'){if(!val('title'))return;if(val('end')<=val('time')){toast('Конец встречи должен быть позже начала.');return;}state.events.push({id:uid(),title:val('title'),date:val('date'),time:val('time'),end:val('end')});savedDialog();toast('Встреча добавлена в календарь демонстрации.');}
});
document.addEventListener('input',e=>{const f=e.target.closest('#modal form');if(f)f.dataset.dirty='true';if(e.target.id==='result-text')state.drafts[selectedInbox].text=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='result-kind'){state.drafts[selectedInbox].type=e.target.value;$('#event-fields').hidden=e.target.value!=='event';$('#result-label').textContent=e.target.value==='task'?'Что конкретно сделать?':'Название или содержание';}});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&$('#modal').open){const f=$('#modal form');if(f){e.preventDefault();f.requestSubmit();}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
setInterval(()=>{const f=state.focus;if(!f?.running)return;if(remaining()===0){f.running=false;f.remaining=0;if(route()==='focus')render();toast('Отрезок закончился. Можно отдохнуть или продолжить.');}else if($('#timer'))$('#timer').textContent=timerText();},500);
render();
